@custom-variant dark (&:where(.dark, .dark *):not(:where(.light, .light *)));
@custom-variant hover (&:hover);
@custom-variant hover-hover {
  @media (hover: hover) and (pointer: fine) {
    &:hover {
      @slot;
    }
  }
}
@theme inline {
  /**
   * Pinned to the v3 default stack. v4's own `--font-sans` is an
   * `-apple-system`-first list, and Preflight resolves the document font through
   * it, so taking the new default would shift the face on every element that
   * does not name a font.
   */
  --font-sans:
    ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol",
    "Noto Color Emoji";

  --font-season: var(--font-season);
  --font-body:
    ui-sans-serif, -apple-system, system-ui, Segoe UI, Helvetica, Apple Color Emoji, Arial,
    sans-serif, Segoe UI Emoji, Segoe UI Symbol;
  --font-mono:
    var(--font-martian-mono, ui-monospace), SFMono-Regular, Menlo, Monaco, Consolas,
    "Liberation Mono", "Courier New", monospace;

  /**
   * Pinned in px. v4's defaults are rem, and rem in a media query resolves
   * against the browser's initial font size rather than `html { font-size }` —
   * so a reader who raised their browser's default text size would get the
   * mobile layout at a desktop width. These are v3's px values unchanged.
   */
  --breakpoint-sm: 640px;
  --breakpoint-md: 768px;
  --breakpoint-lg: 1024px;
  --breakpoint-xl: 1280px;
  --breakpoint-2xl: 1536px;

  --text-micro: 10px;
  /**
   * `xs` is the one size here that also exists in Tailwind's own scale, so it
   * inherits `--text-xs--line-height` unless that is overridden too. v4's ratio
   * (4/3) against an 11px size yields 14.67px, where v3 resolved 16.5px; the
   * paired value keeps the leading where it was.
   */
  --text-xs: 11px;
  --text-xs--line-height: 1.5;
  --text-caption: 12px;
  --text-small: 13px;
  --text-base: 15px;
  --text-md: 16px;

  /**
   * Hairline scale key. Overriding `spacing` rather than `width`/`height` keeps
   * every derived scale in agreement — a `w-px` line and the `-right-px` offset
   * that positions it resolve to the same value, which a width-only override
   * desynchronizes by half a device pixel.
   */
  --spacing-px: var(--border-width);

  --color-background: hsl(var(--background));
  --color-foreground: hsl(var(--foreground));
  --color-card: hsl(var(--card));
  --color-card-foreground: hsl(var(--card-foreground));
  --color-popover: hsl(var(--popover));
  --color-popover-foreground: hsl(var(--popover-foreground));
  --color-primary: hsl(var(--primary));
  --color-primary-foreground: hsl(var(--primary-foreground));
  --color-secondary: hsl(var(--secondary));
  --color-secondary-foreground: hsl(var(--secondary-foreground));
  --color-muted: hsl(var(--muted));
  --color-muted-foreground: hsl(var(--muted-foreground));
  --color-accent: hsl(var(--accent));
  --color-accent-foreground: hsl(var(--accent-foreground));
  --color-destructive: hsl(var(--destructive));
  --color-destructive-foreground: hsl(var(--destructive-foreground));

  /**
   * Neutral border colors are plain hex, not the HSL triplets the shadcn keys
   * above use — `hsl(var(--border))` would be invalid CSS and get dropped,
   * leaving the utility to fall through to the `*` border-color rule below by
   * accident.
   */
  --color-border: var(--border);
  --color-input: hsl(var(--input));
  --color-ring: hsl(var(--ring));

  --color-chart-1: hsl(var(--chart-1));
  --color-chart-2: hsl(var(--chart-2));
  --color-chart-3: hsl(var(--chart-3));
  --color-chart-4: hsl(var(--chart-4));
  --color-chart-5: hsl(var(--chart-5));

  /**
   * v4 ships its palette in oklch, which renders visibly more saturated than
   * v3's sRGB hex on a P3 display. These are the v3 values for every stock
   * palette colour the app actually uses, recovered from a v3 build, so the
   * upgrade changes no rendered colour. Adopting the wider-gamut palette is a
   * design decision to make on its own, not a side effect of the upgrade.
   */
  --color-amber-50: #fffbeb;
  --color-amber-200: #fde68a;
  --color-amber-300: #fcd34d;
  --color-amber-400: #fbbf24;
  --color-amber-500: #f59e0b;
  --color-amber-600: #d97706;
  --color-amber-700: #b45309;
  --color-amber-800: #92400e;
  --color-amber-900: #78350f;
  --color-amber-950: #451a03;
  --color-blue-500: #3b82f6;
  --color-emerald-400: #34d399;
  --color-emerald-500: #10b981;
  --color-green-500: #22c55e;
  --color-orange-400: #fb923c;
  --color-purple-500: #a855f7;
  --color-red-50: #fef2f2;
  --color-red-300: #fca5a5;
  --color-red-400: #f87171;
  --color-red-600: #dc2626;
  --color-red-700: #b91c1c;
  --color-red-950: #450a0a;
  --color-yellow-200: #fef08a;
  --color-yellow-500: #eab308;

  --color-gray-50: #fafafa;
  --color-gray-100: #f5f5f5;
  --color-gray-200: #e5e5e5;
  --color-gray-300: #d4d4d4;
  --color-gray-400: #a3a3a3;
  --color-gray-500: #737373;
  --color-gray-600: #525252;
  --color-gray-700: #404040;
  --color-gray-800: #262626;
  --color-gray-900: #171717;
  --color-gray-950: #0a0a0a;

  --radius-xs: 2px;
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);

  /**
   * These names intentionally match the app's own `:root` custom properties, so
   * the value below reads back as a self-reference. It resolves: Tailwind emits
   * the theme copy inside `@layer theme`, and the app's later unlayered `:root`
   * declaration outranks any layered one, so the real value always wins. The
   * `inline` substitution then resolves it at the element, which is what lets
   * `.dark` override each shadow.
   */
  --shadow-subtle: var(--shadow-subtle);
  --shadow-medium: var(--shadow-medium);
  --shadow-overlay: var(--shadow-overlay);
  --shadow-kbd: var(--shadow-kbd);
  --shadow-kbd-sm: var(--shadow-kbd-sm);
  --shadow-card: var(--shadow-card);
  --shadow-ambient: var(--shadow-ambient);

  /**
   * The home/chat reading column. The heading, input, suggested actions,
   * transcript, and its skeleton must all share one value or the footer input
   * visibly misaligns with the messages above it — so they read this key rather
   * than repeating a literal.
   */
  --container-chat: 44rem;

  --animate-caret-blink: caret-blink 1.25s ease-out infinite;
  --animate-running-hatch-scroll: running-hatch-scroll 900ms linear infinite;
  --animate-ring-pulse: ring-pulse 1.5s ease-in-out infinite;
  --animate-stream-fade-in: stream-fade-in 300ms ease-out forwards;
  --animate-slide-in-bottom: slide-in-bottom 400ms cubic-bezier(0.16, 1, 0.3, 1);
  /* Deliberately slower than tw-animate-css's own 200ms ease-out default. */
  --animate-collapsible-down: collapsible-down 300ms cubic-bezier(0.4, 0, 0.2, 1);
  --animate-collapsible-up: collapsible-up 300ms cubic-bezier(0.4, 0, 0.2, 1);
  --animate-hero-cursor-press: hero-cursor-press 340ms cubic-bezier(0.23, 1, 0.32, 1);
  --animate-hero-modal-in: hero-modal-in 320ms cubic-bezier(0.16, 1, 0.3, 1) both;
  --animate-hero-kb-content-morph: hero-kb-content-morph 420ms cubic-bezier(0.22, 1, 0.36, 1) 260ms
    forwards;
  --animate-hero-file-drop: hero-file-drop 480ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
  --animate-hero-node-pop: hero-node-pop 440ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
  --animate-hero-edge-draw: hero-edge-draw 520ms ease-out forwards;
}
